import java.util.Comparator;
import java.util.PriorityQueue;

public final class StablePriorityQueue {
    private static final class Item {
        final int priority;
        final String value;

        Item(int priority, String value) {
            this.priority = priority;
            this.value = value;
        }
    }

    private final PriorityQueue<Item> heap =
            new PriorityQueue<>(Comparator.comparingInt(i -> i.priority));

    public void push(int priority, String value) {
        heap.add(new Item(priority, value));
    }

    public String pop() {
        return heap.poll().value;
    }

    public int size() {
        return heap.size();
    }
}

