import java.util.Comparator;
import java.util.PriorityQueue;

public final class StablePriorityQueue {
    private static final class Item {
        final int priority;
        final long order;
        final String value;

        Item(int priority, long order, String value) {
            this.priority = priority;
            this.order = order;
            this.value = value;
        }
    }

    private final PriorityQueue<Item> heap = new PriorityQueue<>(
            Comparator.<Item>comparingInt(i -> i.priority).thenComparingLong(i -> i.order));
    private long counter = 0;

    public void push(int priority, String value) {
        heap.add(new Item(priority, counter++, value));
    }

    public String pop() {
        return heap.poll().value;
    }

    public int size() {
        return heap.size();
    }
}

