public final class StablePriorityQueueTest {
    public static void main(String[] args) {
        checkPriorityOrder();
        checkEqualPriorityIsFifo();
        System.out.println("all tests passed");
    }

    static void checkPriorityOrder() {
        StablePriorityQueue q = new StablePriorityQueue();
        q.push(5, "low");
        q.push(1, "high");
        q.push(3, "mid");
        String[] got = {q.pop(), q.pop(), q.pop()};
        String[] want = {"high", "mid", "low"};
        for (int i = 0; i < 3; i++) {
            if (!got[i].equals(want[i])) throw new AssertionError("got " + got[i] + " want " + want[i]);
        }
    }

    static void checkEqualPriorityIsFifo() {
        StablePriorityQueue q = new StablePriorityQueue();
        for (int i = 0; i < 20; i++) {
            q.push(1, String.valueOf((char) ('a' + i)));
        }
        for (int i = 0; i < 20; i++) {
            String got = q.pop();
            String want = String.valueOf((char) ('a' + i));
            if (!got.equals(want)) throw new AssertionError("pop " + i + ": got " + got + " want " + want);
        }
    }
}

